let formData = {
  date: '',
  ru_name: '',
  start_date: '',
  end_date: ''
};

function handleAddPeriod() {
  selectedPeriod = null;
  formData = {
    date: '',
    ru_name: '',
    start_date: '',
    end_date: ''
  };
  showAddModal = true;
}

